const char *CldrStr(int32_t idx)
{
    if (idx < 0 || (size_t)idx >= CldrStringCount) {
        return "";
    }
    return CldrStrings[idx];
}

int32_t CldrFindStr(const char *s)
{
    size_t lo = 0;
    size_t hi = CldrStrOrderCount;
    if (!s) {
        return -1;
    }
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        int32_t idx = CldrStrOrder[mid];
        int cmp = strcmp(s, CldrStrings[idx]);
        if (cmp == 0) {
            return idx;
        }
        if (cmp < 0) {
            hi = mid;
        } else {
            lo = mid + 1u;
        }
    }
    return -1;
}

int32_t CldrKvLookup(const CldrKv *table, size_t count, int32_t key)
{
    size_t lo = 0;
    size_t hi = count;
    if (!table || key < 0) {
        return -1;
    }
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        if (table[mid].key == key) {
            return table[mid].value;
        }
        if (table[mid].key < key) {
            lo = mid + 1u;
        } else {
            hi = mid;
        }
    }
    return -1;
}

const CldrNsys *CldrNsysFind(int32_t id)
{
    size_t lo = 0;
    size_t hi = CldrNsysCount;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        if (CldrNsysTable[mid].id == id) {
            return &CldrNsysTable[mid];
        }
        if (CldrNsysTable[mid].id < id) {
            lo = mid + 1u;
        } else {
            hi = mid;
        }
    }
    return NULL;
}

const CldrCalpref *CldrCalprefFind(int32_t region)
{
    size_t lo = 0;
    size_t hi = CldrCalprefCount;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        if (CldrCalprefTable[mid].region == region) {
            return &CldrCalprefTable[mid];
        }
        if (CldrCalprefTable[mid].region < region) {
            lo = mid + 1u;
        } else {
            hi = mid;
        }
    }
    return NULL;
}

const CldrLocNum *CldrLocNumFind(int32_t locale)
{
    size_t lo = 0;
    size_t hi = CldrLocNumCount;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        if (CldrLocNumTable[mid].locale == locale) {
            return &CldrLocNumTable[mid];
        }
        if (CldrLocNumTable[mid].locale < locale) {
            lo = mid + 1u;
        } else {
            hi = mid;
        }
    }
    return NULL;
}

const CldrNumfmt *CldrNumfmtFind(int32_t locale, int32_t nsys)
{
    size_t lo = 0;
    size_t hi = CldrNumfmtCount;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        const CldrNumfmt *row = &CldrNumfmtTable[mid];
        if (row->locale == locale && row->nsys == nsys) {
            return row;
        }
        if (row->locale < locale || (row->locale == locale && row->nsys < nsys)) {
            lo = mid + 1u;
        } else {
            hi = mid;
        }
    }
    return NULL;
}

